#!/usr/bin/env node

import fs from "node:fs";
import path from "node:path";
import process from "node:process";

import { parseFlags, usage } from "../src/args.mjs";
import { loadConfig, repoRootFromScript } from "../src/config.mjs";
import { runContextCommand } from "../src/context/cli.mjs";
import { doctor } from "../src/doctor.mjs";
import { exportProvider } from "../src/export.mjs";
import { installProvider } from "../src/install.mjs";
import { runGraphCommand } from "../src/vitaegraph/cli.mjs";
import { listCommands, listProviders, listSkills } from "../src/list.mjs";
import { templateContext } from "../src/template.mjs";
import { uninstallProvider } from "../src/uninstall.mjs";
import { checkForUpdates } from "../src/update.mjs";
import { showVersion } from "../src/version.mjs";
import { mcpServerOptions, startMcpStdioServer } from "../src/mcp/server.mjs";

const invokedAs = path.basename(process.argv[1] ?? "vitaecontext");
if (invokedAs === "agentkit-seo") {
  console.error(
    "warning: 'agentkit-seo' is deprecated and kept as a compatibility alias; use 'vitaecontext' instead."
  );
}

async function run() {
  const [, , command, ...rest] = process.argv;
  if (!command || command === "help" || command === "--help" || command === "-h") {
    usage();
    return;
  }

  const repoRoot = repoRootFromScript(import.meta.url);
  const config = loadConfig(repoRoot);

  if (command === "version") {
    showVersion(config);
    return;
  }

  if (command === "mcp") {
    const flags = parseFlags(rest);
    startMcpStdioServer(repoRoot, config, mcpServerOptions(flags));
    return;
  }

  if (command === "update") {
    const flags = parseFlags(rest);
    await checkForUpdates(config, flags);
    return;
  }

  if (command === "doctor") {
    parseFlags(rest);
    doctor(repoRoot, config);
    return;
  }

  if (command === "template") {
    const subject = rest[0];
    const flags = parseFlags(rest.slice(1));
    if (subject === "context") {
      templateContext(repoRoot, flags);
      return;
    }
    throw new Error("Usage: vitaecontext template context [--output <file>] [--force]");
  }

  if (command === "context") {
    const subject = rest[0];
    const hasFile = subject === "validate" || subject === "summary";
    const filePath = hasFile ? rest[1] : null;
    const flags = parseFlags(rest.slice(hasFile ? 2 : 1));
    runContextCommand(repoRoot, subject, filePath, flags);
    return;
  }

  if (command === "graph") {
    const subject = rest[0];
    const flags = parseFlags(rest.slice(1));
    runGraphCommand(repoRoot, subject, flags);
    return;
  }

  if (command === "list") {
    const subject = rest[0];
    const flags = parseFlags(rest.slice(1));
    if (subject === "providers") {
      listProviders(config);
      return;
    }
    if (subject === "skills") {
      listSkills(config);
      return;
    }
    if (subject === "commands") {
      if (!flags.provider) {
        throw new Error("Usage: vitaecontext list commands --provider <provider>");
      }
      listCommands(config, flags.provider);
      return;
    }
    throw new Error("Usage: vitaecontext list providers|skills|commands --provider <provider>");
  }

  if (command === "install") {
    const flags = parseFlags(rest);
    if (!flags.provider) {
      throw new Error(
        "Usage: vitaecontext install --provider <provider> [--project-root <dir>|--target-dir <dir>] [--commands-target-dir <dir>] [--force]"
      );
    }
    if (flags.provider === "all") {
      throw new Error("Install accepts one provider at a time so destinations stay explicit.");
    }
    if (!config.providers[flags.provider]) {
      const available = Object.keys(config.providers).sort().join(", ");
      throw new Error(`Unknown provider '${flags.provider}'. Available: ${available}`);
    }
    installProvider(repoRoot, flags.provider, config, flags);
    return;
  }

  if (command === "uninstall") {
    const flags = parseFlags(rest);
    if (!flags.provider) {
      throw new Error(
        "Usage: vitaecontext uninstall --provider <provider> [--project-root <dir>|--target-dir <dir>] [--dry-run] [--force]"
      );
    }
    if (flags.provider === "all") {
      throw new Error("Uninstall accepts one provider at a time so destinations stay explicit.");
    }
    if (!config.providers[flags.provider]) {
      const available = Object.keys(config.providers).sort().join(", ");
      throw new Error(`Unknown provider '${flags.provider}'. Available: ${available}`);
    }
    uninstallProvider(repoRoot, flags.provider, config, flags);
    return;
  }

  if (command !== "export") {
    throw new Error(`Unknown command: ${command}`);
  }

  const flags = parseFlags(rest);
  if (!flags.provider || !flags.output) {
    throw new Error("Usage: vitaecontext export --provider <provider|all> --output <dir> [--force]");
  }

  const providers = config.providers;
  const selected =
    flags.provider === "all"
      ? Object.keys(providers)
      : [flags.provider];

  for (const provider of selected) {
    if (!providers[provider]) {
      const available = [...Object.keys(providers).sort(), "all"].join(", ");
      throw new Error(`Unknown provider '${provider}'. Available: ${available}`);
    }
  }

  const outputRoot = path.resolve(flags.output);
  fs.mkdirSync(outputRoot, { recursive: true });

  for (const provider of selected) {
    exportProvider(repoRoot, outputRoot, provider, config, Boolean(flags.force));
  }

  console.log(`Exported ${selected.length} provider bundle(s) to ${outputRoot}`);
  for (const provider of selected) {
    console.log(`- ${provider}: ${path.join(outputRoot, provider)}`);
  }
}

run().catch((error) => {
  console.error(`error: ${error.message}`);
  process.exit(1);
});

import process from "node:process";

import { initializeContext } from "./init.mjs";
import { validateContextFile } from "./parse.mjs";
import { writeContextSummary } from "./summary.mjs";

function printDiagnostics(result) {
  for (const warning of result.warnings) console.warn(`warning: ${result.path}:${warning.line}: ${warning.message} [${warning.code}]`);
  for (const error of result.errors) console.error(`error: ${result.path}:${error.line}: ${error.message} [${error.code}]`);
}

function validationJson(result) {
  return {
    schemaVersion: result.schemaVersion,
    valid: result.valid,
    path: result.path,
    title: result.title,
    sectionNames: result.sections.map((section) => section.normalized),
    errors: result.errors,
    warnings: result.warnings
  };
}

export function runContextCommand(repoRoot, subject, filePath, flags) {
  if (subject === "init") {
    const destination = initializeContext(repoRoot, flags.output, Boolean(flags.force));
    if (flags.json) process.stdout.write(`${JSON.stringify({ schemaVersion: 2, path: destination }, null, 2)}\n`);
    else console.log(`Initialized Career Context at ${destination}`);
    return;
  }
  if (subject === "validate") {
    if (!filePath) throw new Error("Usage: vitaecontext context validate <file> [--json]");
    const result = validateContextFile(filePath);
    if (flags.json) process.stdout.write(`${JSON.stringify(validationJson(result), null, 2)}\n`);
    else {
      printDiagnostics(result);
      if (result.valid) console.log(`Career Context valid: ${result.path}`);
    }
    if (!result.valid) process.exitCode = 1;
    return;
  }
  if (subject === "summary") {
    if (!filePath) throw new Error("Usage: vitaecontext context summary <file> --for <surface> [--output <file>] [--json]");
    const result = writeContextSummary(filePath, flags.for ?? "general", flags.output);
    if (flags.json) process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    else if (result.output) console.log(`Wrote ${result.surface} Career Context packet to ${result.output}`);
    else process.stdout.write(result.content);
    return;
  }
  throw new Error("Usage: vitaecontext context init|validate|summary");
}

import process from "node:process";

import { listMcpResources, readMcpResource } from "./resources.mjs";
import { callMcpTool, listMcpTools } from "./tools.mjs";
import { getMcpPrompt, listMcpPrompts } from "./prompts.mjs";
import { McpProtocolError } from "./errors.mjs";

const PROTOCOL_VERSION = "2024-11-05";
const MAX_MESSAGE_BYTES = 10_000_000;

function isObject(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

export function mcpServerOptions(flags = {}) {
  const allowed = new Set(["context", "context-path", "root", "vitaegraph"]);
  const unknown = Object.keys(flags).find((flag) => !allowed.has(flag));
  if (unknown) throw new Error(`Unknown MCP flag: --${unknown}`);
  if (flags.context && flags["context-path"]) {
    throw new Error("Use only one of --context or --context-path");
  }
  if (flags.root && flags.vitaegraph) {
    throw new Error("Use only one of --root or --vitaegraph");
  }
  return {
    contextPath: flags.context || flags["context-path"],
    vitaegraphRoot: flags.root || flags.vitaegraph
  };
}

function sendJsonRpcResponse(id, result) {
  const response = {
    jsonrpc: "2.0",
    id,
    result
  };
  const body = JSON.stringify(response);
  process.stdout.write(`${body}\n`);
}

function sendJsonRpcError(id, code, message, data = undefined) {
  const response = {
    jsonrpc: "2.0",
    id,
    error: {
      code,
      message,
      ...(data !== undefined ? { data } : {})
    }
  };
  const body = JSON.stringify(response);
  process.stdout.write(`${body}\n`);
}

export async function handleMcpRequest(request, repoRoot, config, options = {}) {
  if (
    !request ||
    !isObject(request) ||
    request.jsonrpc !== "2.0" ||
    typeof request.method !== "string"
  ) {
    sendJsonRpcError(null, -32600, "Invalid Request");
    return;
  }

  const { id, method, params } = request;

  // JSON-RPC notifications omit id. A present null id still receives a response.
  if (!Object.hasOwn(request, "id")) {
    if (method === "notifications/initialized") {
      return;
    }
    return;
  }

  if (id !== null && typeof id !== "string" && typeof id !== "number") {
    sendJsonRpcError(null, -32600, "Invalid Request");
    return;
  }

  if (params !== undefined && !isObject(params)) {
    sendJsonRpcError(id, -32602, "Invalid params: expected an object");
    return;
  }

  try {
    switch (method) {
      case "initialize": {
        if (
          typeof params?.protocolVersion !== "string" ||
          !isObject(params.capabilities) ||
          !isObject(params.clientInfo) ||
          typeof params.clientInfo.name !== "string" ||
          typeof params.clientInfo.version !== "string"
        ) {
          throw new McpProtocolError(-32602, "initialize requires protocolVersion, capabilities, and clientInfo");
        }
        sendJsonRpcResponse(id, {
          protocolVersion: PROTOCOL_VERSION,
          capabilities: {
            resources: { listChanged: false },
            tools: { listChanged: false },
            prompts: { listChanged: false }
          },
          serverInfo: {
            name: config.package?.name ?? "vitaecontext",
            version: config.package?.version ?? "unknown"
          }
        });
        break;
      }

      case "ping": {
        sendJsonRpcResponse(id, {});
        break;
      }

      case "resources/list": {
        const result = listMcpResources(repoRoot, config, options);
        sendJsonRpcResponse(id, { resources: result.resources });
        break;
      }

      case "resources/read": {
        if (typeof params?.uri !== "string" || !params.uri) {
          throw new McpProtocolError(-32602, "resources/read requires a non-empty uri string");
        }
        const result = readMcpResource(params.uri, repoRoot, config, options);
        sendJsonRpcResponse(id, result);
        break;
      }

      case "resources/templates/list": {
        sendJsonRpcResponse(id, {
          resourceTemplates: [
            {
              uriTemplate: "vitaegraph://record/{id}",
              name: "VitaeGraph Record",
              description: "Read a specific VitaeGraph record Markdown by ID.",
              mimeType: "text/markdown"
            },
            {
              uriTemplate: "vitaecontext://wiki/{module}",
              name: "VitaeContext Module Wiki",
              description: "Read platform rules and wiki knowledge by module.",
              mimeType: "text/markdown"
            }
          ]
        });
        break;
      }

      case "tools/list": {
        const result = listMcpTools();
        sendJsonRpcResponse(id, result);
        break;
      }

      case "tools/call": {
        if (typeof params?.name !== "string" || !params.name) {
          throw new McpProtocolError(-32602, "tools/call requires a non-empty tool name");
        }
        const result = await callMcpTool(params.name, params.arguments ?? {}, repoRoot, config, options);
        sendJsonRpcResponse(id, result);
        break;
      }

      case "prompts/list": {
        const result = listMcpPrompts();
        sendJsonRpcResponse(id, result);
        break;
      }

      case "prompts/get": {
        if (typeof params?.name !== "string" || !params.name) {
          throw new McpProtocolError(-32602, "prompts/get requires a non-empty prompt name");
        }
        const result = getMcpPrompt(params.name, params.arguments ?? {}, repoRoot, config, options);
        sendJsonRpcResponse(id, result);
        break;
      }

      default: {
        sendJsonRpcError(id, -32601, `Method not found: ${method}`);
        break;
      }
    }
  } catch (error) {
    if (error instanceof McpProtocolError) {
      sendJsonRpcError(id, error.code, error.message, error.data);
      return;
    }
    process.stderr.write(`MCP server error: ${error.message}\n`);
    sendJsonRpcError(id, -32603, "Internal error");
  }
}

export function startMcpStdioServer(repoRoot, config, options = {}) {
  let buffer = "";
  let processing = Promise.resolve();

  process.stdin.setEncoding("utf8");

  const enqueue = (request) => {
    processing = processing
      .then(() => handleMcpRequest(request, repoRoot, config, options))
      .catch((error) => {
        process.stderr.write(`MCP server fatal request error: ${error.message}\n`);
      });
  };

  process.stdin.on("data", (chunk) => {
    buffer += chunk;

    while (buffer.length > 0) {
      const newlineIndex = buffer.indexOf("\n");
      if (newlineIndex === -1) {
        if (Buffer.byteLength(buffer, "utf8") > MAX_MESSAGE_BYTES) {
          buffer = "";
          sendJsonRpcError(null, -32700, "Parse error: message exceeds 10 MB limit");
        }
        break;
      }

      const line = buffer.slice(0, newlineIndex).trim();
      buffer = buffer.slice(newlineIndex + 1);

      if (!line) continue;
      if (Buffer.byteLength(line, "utf8") > MAX_MESSAGE_BYTES) {
        sendJsonRpcError(null, -32700, "Parse error: message exceeds 10 MB limit");
        continue;
      }

      try {
        enqueue(JSON.parse(line));
      } catch {
        sendJsonRpcError(null, -32700, "Parse error");
      }
    }
  });

  process.on("SIGINT", () => process.exit(0));
  process.on("SIGTERM", () => process.exit(0));
}

import path from "node:path";

import { initializeVitaeGraph, resolveVitaeGraphRoot } from "./init.mjs";
import { writeVitaeGraphArtifacts } from "./index.mjs";
import { validateVitaeGraph } from "./validate.mjs";

function graphRoot(flags) {
  return resolveVitaeGraphRoot(flags.root);
}

export function runGraphCommand(repoRoot, subject, flags) {
  if (subject === "init") {
    const root = initializeVitaeGraph(repoRoot, flags.root, Boolean(flags.force));
    console.log(`Initialized VitaeGraph at ${root}`);
    return;
  }
  if (subject === "validate") {
    const root = graphRoot(flags);
    const result = validateVitaeGraph(root);
    for (const warning of result.warnings) console.warn(`warning: ${warning.path}: ${warning.message}`);
    for (const error of result.errors) console.error(`error: ${error.path}: ${error.message}`);
    if (!result.valid) throw new Error(`VitaeGraph validation failed with ${result.errors.length} error(s)`);
    console.log(`VitaeGraph valid: ${result.recordCount} record(s) at ${path.resolve(root)}`);
    return;
  }
  if (subject === "index") {
    const root = graphRoot(flags);
    const result = writeVitaeGraphArtifacts(root);
    console.log(`Indexed ${result.graph.nodes.length} VitaeGraph node(s)`);
    console.log(`- generated: ${result.generated}`);
    return;
  }
  throw new Error("Usage: vitaecontext graph init|validate|index [--root <vitaegraph-directory>] [--force]");
}

import fs from "node:fs";
import path from "node:path";

import { writeJsonFile } from "../filesystem.mjs";
import { validateVitaeGraph } from "./validate.mjs";

function asList(value) {
  if (value === undefined || value === null || value === "") return [];
  return Array.isArray(value) ? value : [value];
}

function nodeType(type) {
  return String(type)
    .split(/[-_\s]+/)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("");
}

function plainText(markdown) {
  return markdown
    .replace(/^---[\s\S]*?---\s*/m, "")
    .replace(/```[\s\S]*?```/g, " ")
    .replace(/!\[[^\]]*\]\([^)]+\)/g, " ")
    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
    .replace(/[#>*_`|~-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function termsFor(text) {
  const terms = {};
  for (const token of text.toLowerCase().match(/[a-z0-9][a-z0-9+.#-]*/g) ?? []) {
    terms[token] = (terms[token] ?? 0) + 1;
  }
  return Object.fromEntries(Object.entries(terms).sort(([a], [b]) => a.localeCompare(b)));
}

export function buildVitaeGraphArtifacts(root) {
  const validation = validateVitaeGraph(root);
  if (!validation.valid) {
    const error = new Error(`VitaeGraph validation failed with ${validation.errors.length} error(s)`);
    error.validation = validation;
    throw error;
  }
  const records = [...validation.graph.records].sort((a, b) =>
    a.attributes.id.localeCompare(b.attributes.id)
  );
  const recordNodes = records.map((record) => ({
    id: record.attributes.id,
    type: nodeType(record.attributes.type),
    label: record.attributes.title,
    path: record.path,
    parent: record.attributes.parent ?? null,
    tags: asList(record.attributes.tags).sort()
  }));
  const nodes = recordNodes;
  const edges = [];
  for (const record of records) {
    if (record.attributes.parent) {
      edges.push({
        source: record.attributes.parent,
        target: record.attributes.id,
        type: "CONTAINS"
      });
    }
    for (const target of asList(record.attributes.related_records).sort()) {
      edges.push({ source: record.attributes.id, target, type: "RELATED_TO" });
    }
  }
  edges.sort((a, b) =>
    `${a.source}\0${a.target}\0${a.type}`.localeCompare(`${b.source}\0${b.target}\0${b.type}`)
  );
  const graph = { version: "2.0.0", source: "vitaegraph", nodes, edges };
  const documents = records.map((record) => {
    const text = plainText(record.body);
    return {
      id: record.attributes.id,
      type: nodeType(record.attributes.type),
      title: record.attributes.title,
      path: record.path,
      text,
      tags: asList(record.attributes.tags).sort(),
      terms: termsFor(`${record.attributes.title} ${asList(record.attributes.tags).join(" ")} ${text}`)
    };
  });
  const searchIndex = { version: "2.0.0", algorithm: "lexical-term-frequency", documents };
  const diagnostics = {
    version: "2.0.0",
    valid: validation.valid,
    records: validation.recordCount,
    errors: validation.errors,
    warnings: validation.warnings
  };
  return { graph, searchIndex, diagnostics };
}

export function writeVitaeGraphArtifacts(root) {
  const generated = path.join(path.resolve(root), ".generated");
  fs.mkdirSync(generated, { recursive: true });
  let artifacts;
  try {
    artifacts = buildVitaeGraphArtifacts(root);
  } catch (error) {
    if (error.validation) {
      for (const staleFile of ["graph.json", "search-index.json"]) {
        fs.rmSync(path.join(generated, staleFile), { force: true });
      }
      writeJsonFile(path.join(generated, "diagnostics.json"), {
        version: "2.0.0",
        valid: false,
        records: error.validation.recordCount,
        errors: error.validation.errors,
        warnings: error.validation.warnings
      });
    }
    throw error;
  }
  writeJsonFile(path.join(generated, "graph.json"), artifacts.graph);
  writeJsonFile(path.join(generated, "search-index.json"), artifacts.searchIndex);
  writeJsonFile(path.join(generated, "diagnostics.json"), artifacts.diagnostics);
  return { generated, ...artifacts };
}

#!/usr/bin/env node

import path from "node:path";
import process from "node:process";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const packageRoot = path.dirname(
  fileURLToPath(import.meta.resolve("vitaecontext/package.json"))
);
const cliPath = path.join(
  packageRoot,
  "bin",
  "vitaecontext.mjs"
);

console.error(
  "warning: 'agentkit-seo' has been renamed to 'vitaecontext'; this compatibility command forwards to VitaeContext."
);

const result = spawnSync(process.execPath, [cliPath, ...process.argv.slice(2)], {
  stdio: "inherit"
});

if (result.error) {
  console.error(`error: unable to start VitaeContext: ${result.error.message}`);
  process.exit(1);
}

if (result.signal) {
  process.kill(process.pid, result.signal);
}

process.exit(result.status ?? 1);
